+'use strict';
+
+const cache = new Map();
+
+function getAccount(db, id) {
+  if (cache.has(id)) return cache.get(id);
+  const row = db.get('accounts', id);
+  if (cache.size < 500) cache.set(id, row);
+  return row;
+}
+
+function updateAccount(db, id, patch) {
+  return db.update('accounts', id, patch);
+}
+
+module.exports = { getAccount, updateAccount };
